    'करुणा सदन मिनिस्ट्रीज़ सदस्यता चलाने और, जहाँ आप चुनें, Jodie विवाह सेवा के लिए आपके पहचान दस्तावेज़, तस्वीर और प्रोफ़ाइल रखेगी। आप कभी भी सहमति वापस ले सकते हैं, जिससे Jodie प्रोफ़ाइल बंद हो जाएगी।',
    'करुणा सदन मिनिस्ट्रीज सदस्यत्व चालवण्यासाठी आणि, तुम्ही निवडल्यास, Jodie विवाह सेवेसाठी तुमची ओळख कागदपत्रे, छायाचित्र आणि प्रोफाइल ठेवेल. तुम्ही कधीही संमती मागे घेऊ शकता, ज्यामुळे Jodie प्रोफाइल बंद होईल.',
    'ಕರುಣಾ ಸದನ್ ಮಿನಿಸ್ಟ್ರೀಸ್ ಸದಸ್ಯತ್ವವನ್ನು ನಡೆಸಲು ಮತ್ತು ನೀವು ಆಯ್ಕೆ ಮಾಡಿದರೆ Jodie ವಿವಾಹ ಸೇವೆಗಾಗಿ ನಿಮ್ಮ ಗುರುತಿನ ದಾಖಲೆಗಳು, ಫೋಟೋ ಮತ್ತು ಪ್ರೊಫೈಲ್ ಅನ್ನು ಇರಿಸಿಕೊಳ್ಳುತ್ತದೆ. ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ಒಪ್ಪಿಗೆ ಹಿಂಪಡೆಯಬಹುದು, ಇದರಿಂದ Jodie ಪ್ರೊಫೈಲ್ ಮುಚ್ಚಲ್ಪಡುತ್ತದೆ.',
    'കരുണ സദൻ മിനിസ്ട്രീസ് അംഗത്വം നടത്തുന്നതിനും, നിങ്ങൾ തിരഞ്ഞെടുത്താൽ Jodie വിവാഹ സേവനത്തിനും നിങ്ങളുടെ തിരിച്ചറിയൽ രേഖകളും ഫോട്ടോയും പ്രൊഫൈലും സൂക്ഷിക്കും. നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും സമ്മതം പിൻവലിക്കാം, ഇത് Jodie പ്രൊഫൈൽ അടയ്ക്കും.',
    'కరుణ సదన్ మినిస్ట్రీస్ సభ్యత్వాన్ని నిర్వహించడానికి మరియు మీరు ఎంచుకుంటే Jodie వివాహ సేవ కోసం మీ గుర్తింపు పత్రాలు, ఫోటో మరియు ప్రొఫైల్‌ను ఉంచుతుంది. మీరు ఎప్పుడైనా సమ్మతిని ఉపసంహరించుకోవచ్చు, దీనివల్ల Jodie ప్రొఫైల్ మూసివేయబడుతుంది.',
    'கருணா சதன் மினிஸ்ட்ரீஸ், உறுப்பினர் சேவையை நடத்தவும், நீங்கள் தேர்ந்தெடுத்தால் Jodie திருமண சேவைக்காகவும், உங்கள் அடையாள ஆவணங்கள், புகைப்படம் மற்றும் சுயவிவரத்தைப் பாதுகாத்து வைத்திருக்கும். எந்த நேரத்திலும் நீங்கள் சம்மதத்தைத் திரும்பப் பெறலாம்; அப்போது Jodie சுயவிவரம் மூடப்படும்.',
  ],
