    'कृपया प्रतीक्षा करा. प्रशासकाने तुमचा तपशील मंजूर केल्यावर तुम्हाला ईमेल मिळेल. हे पृष्ठ पाहण्यासाठी त्याच क्रमांकाने पुन्हा साइन इन करा.',
    'ದಯವಿಟ್ಟು ಕಾಯಿರಿ. ನಿರ್ವಾಹಕರು ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಅನುಮೋದಿಸಿದಾಗ ನಿಮಗೆ ಇಮೇಲ್ ಬರುತ್ತದೆ. ಈ ಪುಟ ನೋಡಲು ಅದೇ ಸಂಖ್ಯೆಯಿಂದ ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'ദയവായി കാത്തിരിക്കുക. അഡ്മിൻ നിങ്ങളുടെ വിവരങ്ങൾ അംഗീകരിക്കുമ്പോൾ നിങ്ങൾക്ക് ഇമെയിൽ ലഭിക്കും. ഈ പേജ് കാണാൻ അതേ നമ്പറിൽ വീണ്ടും സൈൻ ഇൻ ചെയ്യുക.',
    'దయచేసి వేచి ఉండండి. అడ్మిన్ మీ వివరాలను ఆమోదించినప్పుడు మీకు ఇమెయిల్ వస్తుంది. ఈ పేజీని చూడటానికి అదే నంబర్‌తో మళ్లీ సైన్ ఇన్ చేయండి.',
    'தயவுசெய்து காத்திருக்கவும். நிர்வாகி உங்கள் விவரங்களை ஒப்புக்கொண்டவுடன் உங்களுக்கு மின்னஞ்சல் வரும். இந்தப் பக்கத்தைப் பார்க்க அதே எண்ணுடன் மீண்டும் உள்நுழையவும்.',
  ],
