'pf_view_note': [
    'You cannot edit these details directly. Tap a detail, enter the new value and send it to the admin. It changes only if the admin accepts it.',
    'आप ये विवरण सीधे नहीं बदल सकते। किसी विवरण पर टैप करें, नया मान लिखें और एडमिन को भेजें। एडमिन के स्वीकार करने पर ही यह बदलेगा।',
    'तुम्ही हे तपशील थेट बदलू शकत नाही. तपशीलावर टॅप करा, नवीन मूल्य लिहा आणि प्रशासकाला पाठवा. प्रशासकाने मान्य केले तरच ते बदलेल.',
    'ನೀವು ಈ ವಿವರಗಳನ್ನು ನೇರವಾಗಿ ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ. ವಿವರದ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ, ಹೊಸ ಮೌಲ್ಯ ನಮೂದಿಸಿ ಮತ್ತು ನಿರ್ವಾಹಕರಿಗೆ ಕಳುಹಿಸಿ. ನಿರ್ವಾಹಕರು ಒಪ್ಪಿದರೆ ಮಾತ್ರ ಬದಲಾಗುತ್ತದೆ.',
